def public_value(column,value):
 if not isinstance(value,str):return value
 if column in {'Synthetic history','Synthetic assay records','Real-data records','Parity records','Supplemental parity records','Control source record','Producer summary record'} and value.startswith(('[','{')):
  try:record=json.loads(value)
  except (ValueError,TypeError):return value
  def walk(v,key=''):
   if isinstance(v,dict):return {k:walk(x,k) for k,x in v.items()}
   if isinstance(v,list):return [walk(x,key) for x in v]
   return public_value(key,v)
  updated=walk(record)
  return json.dumps(updated,ensure_ascii=False) if updated!=record else value
 value=_PUBLIC_TABLE_VALUES.get(value,value)
 if column in _PUBLIC_PROSE_COLUMNS or column=='split':value=_PUBLIC_NOTES.get(_public_hashlib.sha256(value.encode()).hexdigest(),value)
 path=column not in {'source_host','baseline'} and (column in _PUBLIC_PATH_FIELDS or _public_re.search(_PUBLIC_PATH_COLUMN,column) and not _public_re.search(_PUBLIC_JOIN_COLUMN,column))
 if path and not _public_re.match(r'^[A-Za-z][A-Za-z0-9+.-]*://',value) and ('/' in value or _public_re.search(r'[.](?:tsv|csv|json|rds|R|py|gz|txt|pkl|tar|xlsx|xls)$',value,_public_re.I)):
  value=_public_re.sub(r'^/(?:[^/]+/)*OmicSelector_paper/','./',value)
  root=os.environ.get('OMICSELECTOR_PAPER_ROOT','')
  if root and value.startswith(root+'/'):value='./'+value[len(root)+1:]
  value=value.replace('delegated_tasks/review_response_20261020/','analyses/').replace('delegated_tasks/complete_all_routes_20261010/','analyses/').replace('delegated_tasks/single_sample_reframe_20261017/','analyses/single_specimen/')
  value=analysis_directory(value)
 return value
def public_records(records):
 return [{key:public_value(key,value) for key,value in row.items()} for row in records]
def public_table(frame):
 if not hasattr(frame,'columns'):return frame
 result=frame.copy()
 for column in frame.columns:
  series=frame[column]
  if getattr(series.dtype,'kind','') in {'O','U','S'} or str(series.dtype)=='category':
   result[column]=[public_value(str(column),value) for value in series]
 result.columns=[_PUBLIC_SCHEMA.get(str(c),c) for c in result.columns]
 return result

PAPER=next(p for p in Path(__file__).resolve().parents if (p/'config/project.json').is_file())
ROOT=Path(os.environ.get('OMICSELECTOR_PAPER_ROOT',str(PAPER/'work'))).resolve()
M=Path('analyses');B=ROOT/analysis_directory(M)/'benchmark_saved_scores'
def rows(p):
 with p.open() as f:result=list(csv.DictReader(f,delimiter='\t'))
 if p.name=='study_output_sha256.tsv':result=[r for r in result if Path(r.get('expected_path','')).name not in {'code_sha256.tsv','lifecycle.tsv'}]
 return result
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1024*1024),b''):h.update(b)
 return h.hexdigest()
def write(p,rs):
 p.parent.mkdir(parents=True,exist_ok=True)
 with p.open('w') as f:
  w=csv.DictWriter(f,fieldnames=list(rs[0]),delimiter='\t',lineterminator='\n');w.writeheader();w.writerows(public_records(rs))
def initialize(bundle):
 ROOT.mkdir(parents=True,exist_ok=True)
 manifest=bundle/'manifest.tsv'
 if not (bundle/'tree').exists():
  for r in rows(bundle/'assets.tsv'):
   p=bundle/analysis_directory(r['file']);assert sha(p)==r['sha256'],p
   with tarfile.open(p,'r:gz') as t:
    for n in t.getmembers():
     dest=(ROOT/analysis_directory(n.name)).resolve()
     if ROOT not in dest.parents or not n.isfile():raise ValueError('Unsafe archive member '+n.name)
    t.extractall(ROOT,filter='data')
 else:
  for r in rows(manifest):
   src=bundle/'tree'/analysis_directory(r['path']);assert sha(src)==r['sha256'],src
   dest=ROOT/analysis_directory(r['path']);dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(src,dest)
 # Verify after extraction/copy. Manifest contains bytes of the portable objects.
 for r in rows(manifest):assert sha(ROOT/analysis_directory(r['path']))==r['sha256'],r['path']
 # Place checksum-matched public sources at their accession-manifest locations.
 by_source_sha={r['sha256']:ROOT/analysis_directory(r['path']) for r in rows(manifest)}
 for r in rows(PAPER/'data/raw_downloads.tsv'):
  destination=ROOT/analysis_directory(r['path']);source=by_source_sha.get(r['expected_sha256'])
  if source is not None and (not destination.is_file() or sha(destination)!=r['expected_sha256']):
   destination.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(source,destination)
   assert sha(destination)==r['expected_sha256']
 shutil.copytree(PAPER/'scripts/producers',ROOT,dirs_exist_ok=True)
 with tarfile.open(ROOT/'software/summary-libraries.tar.gz','r:gz') as t:t.extractall(ROOT/'runtime/r-library',filter='data')
 with tarfile.open(ROOT/'software/summary-jsonlite.tar.gz','r:gz') as t:t.extractall(ROOT/'runtime/r-library',filter='data')
 with tarfile.open(ROOT/'software/summary-runtime.tar.gz','r:gz') as t:t.extractall(ROOT/'runtime/R',filter='data')
 shim=ROOT/'runtime/bin/Rscript';shim.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(PAPER/'scripts/computing_bundle/rscript.py',shim);shim.chmod(0o755)
 for p in [ROOT/'runtime/tmp',ROOT/'runtime/cache',B/'out/logs',B/'out/synthesis/logs',B/'tmp']:p.mkdir(parents=True,exist_ok=True)
 shutil.copytree(B/'scripts',B/'out/synthesis/scripts',dirs_exist_ok=True)
